ALTER TABLE apikamgusv2.models ADD CONSTRAINT models_status_chk CHECK (status IN ('A', 'I')) NOT VALID;
ALTER TABLE apikamgusv2.qualifications ADD CONSTRAINT qualifications_status_chk CHECK (status IN ('A', 'I')) NOT VALID;
ALTER TABLE apikamgusv2.services ADD CONSTRAINT services_tipo_transporte_chk CHECK (tipo_transporte IN ('MOTO', 'SEDAN', 'PANEL', 'PICK UP', 'CAMIÓN PEQUEÑO', 'CAMIÓN GRANDE')) NOT VALID;
ALTER TABLE apikamgusv2.services ADD CONSTRAINT services_tipo_servicio_chk CHECK (tipo_servicio IN ('SIMPLE', 'MUDANZA')) NOT VALID;
ALTER TABLE apikamgusv2.services ADD CONSTRAINT services_estado_chk CHECK (estado IN ('ACTIVO', 'AGENDADO', 'INACTIVO', 'PENDIENTE', 'CANCELADO', 'ANULADO', 'TERMINADO', 'RESERVA', 'PROGRAMAR', 'REPETIR')) NOT VALID;
