ALTER TABLE apikamgusv2.service_statuses ADD CONSTRAINT service_statuses_status_chk CHECK (status IN ('Nuevo servicio', 'Servicio rechazado', 'Estado de servicio', 'Conductor activo', 'Llego al punto B', 'Descargado', 'Servicio finalizado')) NOT VALID;
